}
import { hasExactKeys, isNonnegativeInteger, isRecord } from './validation.ts';
import { MISMATCH_MS } from './state.ts';
import type { GameState, Selection } from './state.ts';

export function decodeSelection(value: unknown, state: GameState, matched: readonly number[]): Selection | null {
  if (!isRecord(value)) return null;
  const eligible = (index: unknown): index is number =>
    isNonnegativeInteger(index, state.deck.length - 1) && !matched.includes(index);
  switch (value.kind) {
    case 'closed': return hasExactKeys(value, ['kind']) ? { kind: 'closed' } : null;
    case 'one':
      return hasExactKeys(value, ['kind', 'index']) && eligible(value.index)
        ? { kind: 'one', index: value.index } : null;
    case 'mismatch':
      if (!hasExactKeys(value, ['kind', 'first', 'second', 'remainingMs'])
        || !eligible(value.first) || !eligible(value.second) || value.first === value.second
        || state.deck[value.first] === state.deck[value.second]
        || !isNonnegativeInteger(value.remainingMs, MISMATCH_MS) || value.remainingMs < 1) return null;
      return { kind: 'mismatch', first: value.first, second: value.second, remainingMs: value.remainingMs };
    default: return null;
  }
}
export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function hasExactKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
  const actual = Object.keys(value);
  return actual.length === keys.length && keys.every(key => Object.hasOwn(value, key));
}

export function isNonnegativeInteger(value: unknown, maximum = Number.MAX_SAFE_INTEGER): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 && value <= maximum;
}

export function parseLimitedJson(text: string, maximumBytes: number): unknown {
  if (new TextEncoder().encode(text).byteLength > maximumBytes) return null;
  try { return JSON.parse(text); } catch { return null; }
}

import { activateCard, advanceGame, createGame } from './state.ts';
import type { GameState } from './state.ts';
import { hasExactKeys, isNonnegativeInteger, isRecord, parseLimitedJson } from './validation.ts';

export const REPLAY_VERSION = 1;
export const MAX_REPLAY_BYTES = 1048576;
export const MAX_REPLAY_ACTIONS = 10000;
type ReplayAction = Readonly<{ atMs: number; index: number }>;

function decodeActions(value: unknown, state: GameState, endMs: number): readonly ReplayAction[] | null {
  if (!Array.isArray(value) || value.length > MAX_REPLAY_ACTIONS) return null;
  const actions: ReplayAction[] = [];
  let previous = 0;
  for (const action of value) {
    if (!isRecord(action) || !hasExactKeys(action, ['atMs', 'index'])
      || !isNonnegativeInteger(action.atMs) || action.atMs < previous || action.atMs > endMs
      || !isNonnegativeInteger(action.index, state.deck.length - 1)) return null;
    actions.push({ atMs: action.atMs, index: action.index });
    previous = action.atMs;
  }
  return actions;
}

export function replayGame(text: string): GameState | null {
  const value = parseLimitedJson(text, MAX_REPLAY_BYTES);
  if (!isRecord(value) || !hasExactKeys(value, ['version', 'boardCode', 'actions', 'endMs'])
    || value.version !== REPLAY_VERSION || typeof value.boardCode !== 'string'
    || !isNonnegativeInteger(value.endMs)) return null;
  let state = createGame(value.boardCode);
  if (!state) return null;
  const actions = decodeActions(value.actions, state, value.endMs);
  if (!actions) return null;
  let previous = 0;
  for (const action of actions) {
    state = activateCard(advanceGame(state, action.atMs - previous), action.index);
    previous = action.atMs;
  }
  return advanceGame(state, value.endMs - previous);
}
import { readFile } from 'node:fs/promises';
import { replayGame, MAX_REPLAY_BYTES } from '../src/game/replay.ts';
import { encodeSnapshot } from '../src/game/snapshot.ts';

async function main(): Promise<void> {
  const path = process.argv[2];
  if (!path || process.argv.length !== 3) throw new Error('Usage: npm run --silent replay -- PATH');
  const bytes = await readFile(path);
  if (bytes.byteLength > MAX_REPLAY_BYTES) throw new Error('Replay exceeds the UTF-8 byte limit.');
  const text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  const state = replayGame(text);
  if (!state) throw new Error('Invalid replay.');
  process.stdout.write(`${encodeSnapshot(state)}\n`);
}

try { await main(); } catch (error) {
  process.stderr.write(`${error instanceof Error ? error.message : 'Unable to read replay.'}\n`);
  process.exitCode = 1;
}
