import { useCallback, useEffect, useRef, useState } from 'react';
import type { GridSize } from '../deck.ts';
import { activateCard, advanceGame, createGame, isWon } from '../state.ts';
import type { GameState } from '../state.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { turnAnnouncement } from './announcements.ts';
import { freshGame } from './freshGame.ts';
import { browserStorage, readPreferences, savePreferences } from './storage.ts';
import type { Preferences } from './storage.ts';

type Session = Readonly<{
  game: GameState; preferences: Preferences; paused: boolean; celebrate: boolean;
  revision: number; notice: string; announcement: string; announcementId: number;
}>;

function initialSession(): Session {
  const preferences = readPreferences(browserStorage());
  return { game: freshGame(preferences.size), preferences, paused: false, celebrate: false,
    revision: 0, notice: '', announcement: '', announcementId: 0 };
}

export function useSession() {
  const [session, setSession] = useState(initialSession);
  const current = useRef(session);
  const timeline = useRef({ last: performance.now(), visible: !document.hidden });
  const generation = useRef(0);
  const publish = useCallback((next: Session) => { current.current = next; setSession(next); }, []);
  const sync = useCallback((): Session => {
    const now = performance.now();
    const before = current.current;
    const delta = Math.max(0, now - timeline.current.last);
    timeline.current.last = now;
    const game = timeline.current.visible && !before.paused ? advanceGame(before.game, delta) : before.game;
    const next = game === before.game ? before : { ...before, game };
    if (next !== before) publish(next);
    return next;
  }, [publish]);

  useEffect(() => {
    const token = ++generation.current;
    let timer: ReturnType<typeof setTimeout> | undefined;
    function schedule() {
      if (generation.current !== token) return;
      const value = current.current;
      if (!timeline.current.visible || value.paused || !value.game.started || isWon(value.game)) return;
      const delay = value.game.selection.kind === 'mismatch' ? Math.min(100, value.game.selection.remainingMs) : 100;
      timer = setTimeout(() => { if (generation.current === token) { sync(); schedule(); } }, delay);
    }
    function visibility() {
      sync();
      timeline.current.visible = !document.hidden;
      if (timer !== undefined) clearTimeout(timer);
      schedule();
    }
    timeline.current.visible = !document.hidden;
    document.addEventListener('visibilitychange', visibility);
    schedule();
    return () => {
      generation.current += 1;
      if (timer !== undefined) clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibility);
    };
  }, [session.revision, session.paused, session.game.started, isWon(session.game), sync]);

  function announce(text: string, notice = current.current.notice): void {
    const before = current.current;
    publish({ ...before, notice, announcement: text, announcementId: before.announcementId + 1 });
  }
  function replace(game: GameState, imported = false): void {
    generation.current += 1;
    timeline.current.last = performance.now();
    const before = current.current;
    const preferences = { ...before.preferences, size: game.board.size };
    savePreferences(browserStorage(), preferences);
    publish({ ...before, game, preferences, paused: imported && !isWon(game), celebrate: false,
      revision: before.revision + 1, notice: '', announcement: '', announcementId: before.announcementId + 1 });
  }
  function activate(index: number): void {
    const before = sync();
    if (before.paused || document.hidden) return;
    const game = activateCard(before.game, index);
    if (game === before.game) return;
    let preferences = before.preferences;
    const won = isWon(game);
    const best = preferences.best[game.board.size];
    if (won && (best === undefined || game.moves < best)) {
      preferences = { ...preferences, best: { ...preferences.best, [game.board.size]: game.moves } };
      savePreferences(browserStorage(), preferences);
    }
    const announcement = turnAnnouncement(before.game, game);
    publish({ ...before, game, preferences, celebrate: won,
      announcement: announcement ?? before.announcement,
      announcementId: before.announcementId + (announcement === null ? 0 : 1) });
  }
  function loadBoard(text: string): boolean {
    const game = createGame(text.trim());
    if (!game) { announce('Invalid board code.', 'Invalid board code.'); return false; }
    replace(game);
    announce('Loaded board.', 'Loaded board.');
    return true;
  }
  function loadSnapshot(text: string): boolean {
    const game = decodeSnapshot(text);
    if (!game) { announce('Invalid snapshot.', 'Invalid snapshot.'); return false; }
    replace(game, true);
    const status = isWon(game) ? 'Loaded completed snapshot.' : 'Loaded snapshot. Select Resume to continue.';
    announce(status, status);
    return true;
  }
  function resume(): void {
    timeline.current.last = performance.now();
    publish({ ...current.current, paused: false });
  }
  function newGame(size: GridSize = current.current.game.board.size): void {
    replace(freshGame(size, current.current.game.board.seed));
  }
  function restart(): void {
    const game = createGame(current.current.game.board.code);
    if (game) replace(game);
  }
  return { ...session, activate, newGame, restart, loadBoard, loadSnapshot, resume,
    exportSnapshot: () => encodeSnapshot(sync().game) };
}

import { GRID_SIZES, isGridSize } from '../deck.ts';
import type { GridSize } from '../deck.ts';
import { MAX_MOVES } from '../state.ts';
import { isNonnegativeInteger, isRecord } from '../validation.ts';

export const PREFERENCES_KEY = 'neon-pairs.preferences.v1';
export type Preferences = Readonly<{ size: GridSize; best: Readonly<Partial<Record<GridSize, number>>> }>;
export type PreferenceStorage = { getItem(key: string): string | null; setItem(key: string, value: string): void };

export function parsePreferences(text: string | null): Preferences {
  const best: Partial<Record<GridSize, number>> = {};
  let size: GridSize = 4;
  try {
    const value: unknown = text === null ? null : JSON.parse(text);
    if (isRecord(value)) {
      if (isGridSize(value.size)) size = value.size;
      if (isRecord(value.best)) {
        for (const candidate of GRID_SIZES) {
          const score = value.best[String(candidate)];
          if (isNonnegativeInteger(score, MAX_MOVES)) best[candidate] = score;
        }
      }
    }
  } catch { /* An invalid preference never prevents play. */ }
  return { size, best };
}

export function browserStorage(): PreferenceStorage | null {
  try { return window.localStorage; } catch { return null; }
}

export function readPreferences(storage: PreferenceStorage | null): Preferences {
  try { return parsePreferences(storage?.getItem(PREFERENCES_KEY) ?? null); }
  catch { return parsePreferences(null); }
}

export function savePreferences(storage: PreferenceStorage | null, preferences: Preferences): void {
  try { storage?.setItem(PREFERENCES_KEY, JSON.stringify(preferences)); } catch { /* Keep playing in memory. */ }
}
export function formatTime(milliseconds: number): string {
  const seconds = Math.floor(milliseconds / 1000);
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
}
import { isWon } from '../state.ts';
import type { GameState } from '../state.ts';
import { formatTime } from './formatTime.ts';

export function turnAnnouncement(before: GameState, after: GameState): string | null {
  if (before.selection.kind !== 'one' || before === after) return null;
  if (after.selection.kind === 'mismatch') return 'No match. Cards close after a short pause.';
  if (after.matched.length === before.matched.length) return null;
  if (isWon(after)) return `Pair found. All pairs found in ${after.moves} moves and ${formatTime(after.elapsedMs)}.`;
  const pairs = after.matched.length / 2;
  return `Pair found. ${pairs} ${pairs === 1 ? 'pair' : 'pairs'} matched.`;
}
import { MAX_SEED } from '../deck.ts';
import type { GridSize } from '../deck.ts';
import { createGame } from '../state.ts';
import type { GameState } from '../state.ts';

export function freshGame(size: GridSize, previousSeed?: number): GameState {
  let value: number;
  try {
    const values = new Uint32Array(1);
    crypto.getRandomValues(values);
    value = values[0] ?? 0;
  } catch { value = Math.floor(Math.random() * 4294967296); }
  let seed = value % MAX_SEED + 1;
  if (seed === previousSeed) seed = seed % MAX_SEED + 1;
  const game = createGame(`np1-${size}-${seed}`);
  if (!game) throw new Error('Unable to create a supported board.');
  return game;
}

export const SHAPES = ['circle', 'square', 'triangle', 'diamond', 'star', 'hexagon', 'plus', 'chevron'] as const;
export const MARKERS = ['top', 'top-right', 'right', 'bottom-right', 'bottom', 'bottom-left', 'left', 'top-left'] as const;
export const FILLS = ['solid', 'outline'] as const;
export const PALETTE = [
  { name: 'cyan', color: '#63E7FF' }, { name: 'magenta', color: '#FF71D6' },
  { name: 'green', color: '#8BEA7D' }, { name: 'yellow', color: '#FFE082' },
  { name: 'orange', color: '#FFB064' }, { name: 'violet', color: '#B49AFF' },
  { name: 'rose', color: '#FF8296' }, { name: 'ice', color: '#D9F3FF' },
] as const;
const DIAGONAL = 40 / Math.sqrt(2);
const OFFSETS = [[0, -40], [DIAGONAL, -DIAGONAL], [40, 0], [DIAGONAL, DIAGONAL],
  [0, 40], [-DIAGONAL, DIAGONAL], [-40, 0], [-DIAGONAL, -DIAGONAL]] as const;

export function faceIdentity(id: number) {
  const shape = SHAPES[id % 8];
  const markerIndex = Math.floor(id / 8) % 8;
  const marker = MARKERS[markerIndex];
  const palette = PALETTE[markerIndex];
  const fill = FILLS[Math.floor(id / 64)];
  const offset = OFFSETS[markerIndex];
  if (!Number.isInteger(id) || id < 0 || id > 127 || !shape || !marker || !palette || !fill || !offset) {
    throw new Error('Invalid face identity.');
  }
  return { shape, marker, fill, color: palette.color, markerX: 50 + offset[0], markerY: 50 + offset[1],
    name: `${palette.name} ${fill} ${shape}, marker ${marker}` };
}
import { faceIdentity } from './face.ts';
